begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_table('public','proposal_files','Completed metadata exists');
select has_table('public','proposal_file_uploads','Upload intents tracked separately');
select is((select public from storage.buckets where id='proposal-files'),false,'Private bucket');
select is((select file_size_limit from storage.buckets where id='proposal-files'),26214400::bigint,'25 MiB');
select is((select count(*)::int from public.role_permissions where permission_key='proposal_files.read'),2,'Only admin/manager receive read');
select ok(not exists(select 1 from public.role_permissions where permission_key='proposal_files.read' and role_key not in ('admin','manager')),'No operator/viewer grant');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.proposal_files'::regclass),'Forced RLS');
select ok(not has_table_privilege('authenticated','public.proposal_files','INSERT,UPDATE,DELETE'),'No user metadata writes');
select ok(not has_table_privilege('authenticated','public.proposal_file_uploads','SELECT'),'No upload capabilities exposed');
select ok(not has_function_privilege('authenticated','public.complete_proposal_file_upload(uuid,uuid,text,bigint,text)','EXECUTE'),'No forged client completion');
insert into organizations(id,legal_name) values('a6103000-0000-4000-8000-000000000001','File QA A'),('a6103000-0000-4000-8000-000000000002','File QA B');
insert into auth.users(id,email) select ('b6103000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'file-qa-'||n||'@example.invalid' from generate_series(1,3)n;
insert into profiles(id,organization_id,full_name,role_key) select id,
 case when email='file-qa-2@example.invalid' then 'a6103000-0000-4000-8000-000000000002'::uuid else 'a6103000-0000-4000-8000-000000000001'::uuid end,
 'File QA',case when email='file-qa-3@example.invalid' then 'operator' else 'manager' end from auth.users where email like 'file-qa-%@example.invalid';
insert into auth.sessions(id,user_id,created_at,updated_at,aal) select id,id,now(),now(),'aal2' from auth.users where email like 'file-qa-%@example.invalid';
insert into financial_institutions(id,organization_id,name) values('c6103000-0000-4000-8000-000000000001','a6103000-0000-4000-8000-000000000001','File QA Bank');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
create function pg_temp.prepare(p_hash text default repeat('a',64),p_actor uuid default 'b6103000-0000-4000-8000-000000000001',p_sync uuid default 'd6103000-0000-4000-8000-000000000001') returns jsonb language sql as $$
 select prepare_proposal_file_upload(p_actor,jsonb_build_object('sync_id',p_sync,'file_kind','pdf','sha256',p_hash,'size_bytes',123,'mime_type','application/pdf','original_filename','synthetic.pdf')) $$;
select throws_ok($$select pg_temp.prepare()$$,'PF404','proposal_not_synced','No object before canonical sync');
select reserve_proposal_number('b6103000-0000-4000-8000-000000000001','d6103000-0000-4000-8000-000000000001','2026-10-30T12:00:00Z');
select sync_desktop_proposal('b6103000-0000-4000-8000-000000000001',jsonb_build_object('sync_id','d6103000-0000-4000-8000-000000000001','proposal_number','2026-0001','proponent_name','Synthetic applicant','created_at','2026-10-30T12:00:00Z','updated_at','2026-10-30T13:00:00Z','created_by_technician_name','Creator QA','responsible_name','Responsible QA','technician_name','Technician QA','bank','File QA Bank','purpose','QA','total_value','100000.00','fno_value','70000.00','of_value','30000.00'));
select throws_ok($$select pg_temp.prepare(repeat('a',64),'b6103000-0000-4000-8000-000000000002')$$,'PF404','proposal_not_synced','Other tenant indistinguishable from missing');
select throws_ok($$select pg_temp.prepare(repeat('a',64),'b6103000-0000-4000-8000-000000000003')$$,'DS403','permission_denied','Operator upload denied');
select is(pg_temp.prepare()->'upload'->>'sha256',repeat('a',64),'Prepare returns authorized hash');
select is(pg_temp.prepare()->'upload'->>'id',pg_temp.prepare()->'upload'->>'id','Prepare retry idempotent');
select is((select count(*)::int from proposal_file_uploads),1,'Only one intent');
select throws_ok($$select complete_proposal_file_upload('b6103000-0000-4000-8000-000000000001',(pg_temp.prepare()->'upload'->>'id')::uuid,repeat('a',64),123,'application/pdf')$$,'PF404','upload_not_found','Cannot complete absent object');
insert into storage.objects(bucket_id,name) select 'proposal-files',storage_path from proposal_file_uploads;
select throws_ok($$select complete_proposal_file_upload('b6103000-0000-4000-8000-000000000001',(pg_temp.prepare()->'upload'->>'id')::uuid,repeat('b',64),123,'application/pdf')$$,'PF409','file_identity_conflict','Verified hash must match');
select is((complete_proposal_file_upload('b6103000-0000-4000-8000-000000000001',(pg_temp.prepare()->'upload'->>'id')::uuid,repeat('a',64),123,'application/pdf')->>'version')::int,1,'First completed version');
select is((complete_proposal_file_upload('b6103000-0000-4000-8000-000000000001',(pg_temp.prepare()->'upload'->>'id')::uuid,repeat('a',64),123,'application/pdf')->>'version')::int,1,'Complete retry idempotent');
select is((select count(*)::int from audit_log where action like 'PROPOSAL_FILE_%'),2,'Only two upload/version events on repeat');
select pg_temp.prepare(repeat('b',64));
insert into storage.objects(bucket_id,name) select 'proposal-files',storage_path from proposal_file_uploads where sha256=repeat('b',64);
select is((complete_proposal_file_upload('b6103000-0000-4000-8000-000000000001',(pg_temp.prepare(repeat('b',64))->'upload'->>'id')::uuid,repeat('b',64),123,'application/pdf')->>'version')::int,2,'New hash new version');
select is((select count(*)::int from proposal_files where is_current),1,'Exactly one current');
select is((select sha256 from proposal_files where is_current),repeat('b',64),'New hash current');
select complete_proposal_file_upload('b6103000-0000-4000-8000-000000000001',(pg_temp.prepare()->'upload'->>'id')::uuid,repeat('a',64),123,'application/pdf');
select is((select sha256 from proposal_files where is_current),repeat('b',64),'Stale retry never rolls back current');
select throws_ok($$select get_proposal_file_download('b6103000-0000-4000-8000-000000000002',(select id from proposal_files limit 1))$$,'PF404','file_not_found','Cross tenant download denied');
select throws_ok($$select get_proposal_file_download('b6103000-0000-4000-8000-000000000003',(select id from proposal_files limit 1))$$,'DS403','permission_denied','No read permission denied');
select audit_proposal_file_download('b6103000-0000-4000-8000-000000000001',(select id from proposal_files where is_current));
select is((select count(*)::int from audit_log where action='PROPOSAL_FILE_DOWNLOAD_AUTHORIZED'),1,'Download authorization audited');
select ok(not exists(select 1 from audit_log where action like 'PROPOSAL_FILE_%' and (changes::text||context::text) ~* 'token|password|secret|signed_url|total_value|fno_value'),'Audit sanitized');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"b6103000-0000-4000-8000-000000000001","aal":"aal2","session_id":"b6103000-0000-4000-8000-000000000001"}',true);
set local role authenticated;
select is((select count(*)::int from proposal_files),2,'Owner AAL2 reads history');
select is((select count(*)::int from storage.objects where bucket_id='proposal-files'),0,'No direct object reads');
reset role;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"b6103000-0000-4000-8000-000000000002","aal":"aal2","session_id":"b6103000-0000-4000-8000-000000000002"}',true);
set local role authenticated;
select is((select count(*)::int from proposal_files),0,'Cross tenant metadata empty');
reset role;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"b6103000-0000-4000-8000-000000000003","aal":"aal2","session_id":"b6103000-0000-4000-8000-000000000003"}',true);
set local role authenticated;
select is((select count(*)::int from proposal_files),0,'Operator metadata empty');
reset role;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"b6103000-0000-4000-8000-000000000001","aal":"aal1","session_id":"b6103000-0000-4000-8000-000000000001"}',true);
set local role authenticated;
select is((select count(*)::int from proposal_files),0,'AAL1 empty');
reset role;
delete from auth.sessions where id='b6103000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"role":"authenticated","sub":"b6103000-0000-4000-8000-000000000001","aal":"aal2","session_id":"b6103000-0000-4000-8000-000000000001"}',true);
set local role authenticated;
select is((select count(*)::int from proposal_files),0,'Revoked signed AAL2 session empty');
reset role;
select * from finish();
rollback;
